script:
(function () {
  'use strict';
  // Lease vs paying cash outright, compared over the lease term, with the opportunity cost of cash.
  // Paying cash
  //   Cash out at signing C = price + sales tax (price x tax rate) + purchase fees.
  //   Value at the end of the term V = price x (1 - yearly depreciation)^(months / 12).
  //   Net cost = C - V. Lost earnings = C x ((1 + j)^T - 1), j = yearly return / 12 (monthly compounding).
  // Leasing (closed-end, standard US method)
  //   Adjusted cap cost A = price - cash down. Residual R = residual % x price.
  //   Base payment = (A - R) / T + (A + R) x money factor, money factor = lease APR / 2400;
  //   payment and cash down are taxed at the sales tax rate. Payments at the start of each month.
  //   Net cost = cash down + its tax + lease fees + payments + end-of-lease charges (the security
  //   deposit is refunded, so it only adds lost earnings).
  //   Lost earnings = sum of each outlay grown to month T at j, minus the outlays themselves.
  // Break-even return: the yearly return at which both totals are equal, found by bisection on 0-30%.
  // Verified in Node (scratchpad tests/auto5): $30,000 cash, no tax or fees, 20%/yr depreciation over
  //   36 months -> net $14,640.00 (30,000 - 30,000 x 0.8^3); lost earnings at 6% = 30,000 x (1.005^36 - 1)
  //   = $5,900.42; lease payment for $50,000, 48% residual, $10,000 down, money factor 0.00208
  //   (4.992% APR), 36 months, 7% tax = $617.99 (same hand check as the site's lease calculator);
  //   lease lost earnings match the annuity-due future value; break-even return makes both totals
  //   equal to the cent; no NaN on blank, zero or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var RETURNS = [0, 2, 4, 6, 8, 10];

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function cash(o, yearly) {
    var j = yearly / 12, tax = o.price * o.taxRate, outlay = o.price + tax + o.buyFees;
    var value = o.price * Math.pow(1 - o.dep, o.T / 12);
    var lost = outlay * (Math.pow(1 + j, o.T) - 1);
    return { tax: tax, outlay: outlay, value: value, net: outlay - value, lost: lost, total: outlay - value + lost };
  }

  function lease(o, yearly) {
    var j = yearly / 12, cap = o.price - o.leaseDown, residual = o.price * o.residualPct, mf = o.leaseApr / 2400;
    var base = (cap - residual) / o.T + (cap + residual) * mf;
    var payment = base * (1 + o.taxRate);
    var upfront = o.leaseDown * (1 + o.taxRate) + o.leaseFees + o.deposit;
    var nominal = upfront, fv = upfront * Math.pow(1 + j, o.T);
    for (var m = 0; m < o.T; m++) { nominal += payment; fv += payment * Math.pow(1 + j, o.T - m); }
    nominal += o.endFees; fv += o.endFees;
    var net = nominal - o.deposit;
    return { payment: payment, upfront: upfront, paid: payment * o.T, net: net, lost: fv - nominal, total: net + fv - nominal };
  }

  function breakEven(o) {
    function gap(r) { return cash(o, r).total - lease(o, r).total; }
    var lo = 0, hi = 0.3, glo = gap(lo), ghi = gap(hi);
    if (glo === 0) return 0;
    if (glo * ghi > 0) return null;
    for (var k = 0; k < 80; k++) {
      var mid = (lo + hi) / 2, g = gap(mid);
      if (g * glo > 0) { lo = mid; glo = g; } else { hi = mid; }
    }
    return (lo + hi) / 2;
  }

  function signed(v) { return (v < 0 ? '−' : '') + money.format(Math.abs(v)); }

  function clearResults() {
    ['lcVerdict', 'lcCashTotal', 'lcLeaseTotal', 'lcLeasePayment', 'lcOutlay', 'lcValue', 'lcBreakEven'].forEach(function (id) { setText(id, '–'); });
    setText('lcVerdictLabel', 'Cheaper option');
    el('lcBreakdown').innerHTML = '';
    el('lcReturns').innerHTML = '';
  }

  function update() {
    var o = {
      price: read('lcPrice'), taxRate: read('lcTaxRate', true), buyFees: read('lcBuyFees', true),
      dep: read('lcDep', true), T: read('lcTerm'), residualPct: read('lcResidual'), leaseApr: read('lcLeaseApr'),
      leaseDown: read('lcLeaseDown', true), leaseFees: read('lcLeaseFees', true), deposit: read('lcDeposit', true),
      endFees: read('lcEndFees', true), invest: read('lcInvest', true)
    };
    var error = el('lcError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(o.T) || o.T < 12 || o.T > 60 || o.T % 1 !== 0) msg = 'Enter a lease term of 12 to 60 whole months.';
    else if (isNaN(o.residualPct) || o.residualPct <= 0 || o.residualPct >= 100) msg = 'Enter a residual value between 0% and 100% of the price.';
    else if (isNaN(o.leaseApr) || o.leaseApr < 0 || o.leaseApr > 40) msg = 'Enter a lease interest rate from 0% to 40%.';
    else if (['taxRate', 'buyFees', 'dep', 'leaseDown', 'leaseFees', 'deposit', 'endFees', 'invest'].some(function (k) { return isNaN(o[k]) || o[k] < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.dep >= 100) msg = 'Enter a yearly depreciation below 100%.';
    else if (o.invest > 30) msg = 'Enter a return of 30% or less.';
    else if (o.price - o.leaseDown <= o.price * o.residualPct / 100) msg = 'The lease cash down brings the cost below the residual value. Lower it.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    o.taxRate /= 100; o.dep /= 100; o.residualPct /= 100;
    var r = o.invest / 100, c = cash(o, r), l = lease(o, r), d = c.total - l.total;
    if (Math.abs(d) < 0.5) {
      setText('lcVerdictLabel', 'Cheaper option');
      setText('lcVerdict', 'About the same');
    } else {
      setText('lcVerdictLabel', d > 0 ? 'Leasing saves you' : 'Paying cash saves you');
      setText('lcVerdict', money.format(Math.abs(d)));
    }
    setText('lcCashTotal', money.format(c.total));
    setText('lcLeaseTotal', money.format(l.total));
    setText('lcLeasePayment', money.format(l.payment));
    setText('lcOutlay', money.format(c.outlay));
    setText('lcValue', money.format(c.value));
    var be = breakEven(o);
    if (be === null) {
      setText('lcBreakEven', cash(o, 0).total < lease(o, 0).total ? 'None: cash wins up to 30%' : 'None: leasing wins at any return');
    } else {
      setText('lcBreakEven', (be * 100).toFixed(2) + '% a year');
    }

    var rows = [
      ['Cash at signing', c.outlay, l.upfront],
      ['Lease payments over ' + o.T + ' months', null, l.paid],
      ['End-of-lease charges', null, o.endFees],
      ['Vehicle value you keep', -c.value, null],
      ['Security deposit returned', null, -o.deposit],
      ['Net cost', c.net, l.net],
      ['Lost investment earnings', c.lost, l.lost],
      ['Total cost incl. lost earnings', c.total, l.total]
    ];
    el('lcBreakdown').innerHTML = rows.map(function (row, idx) {
      var strong = idx === rows.length - 1 ? ' class="font-semibold"' : '';
      return '<tr' + strong + '><th scope="row">' + row[0] + '</th><td>' + (row[1] === null ? '—' : signed(row[1])) +
        '</td><td>' + (row[2] === null ? '—' : signed(row[2])) + '</td></tr>';
    }).join('');

    el('lcReturns').innerHTML = RETURNS.map(function (pctRet) {
      var cc = cash(o, pctRet / 100), ll = lease(o, pctRet / 100), dd = cc.total - ll.total;
      var better = Math.abs(dd) < 0.5 ? 'About the same' : (dd > 0 ? 'Lease by ' : 'Cash by ') + money.format(Math.abs(dd));
      return '<tr><td>' + pctRet + '%</td><td>' + money.format(cc.total) + '</td><td>' + money.format(ll.total) +
        '</td><td>' + better + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
